INSERT INTO `tb_agent_info` (`AgentID`, `Name`, `AICON`, `MemberID`, `MemberName`, `DicIDList`, `DicNameList`, `Description`, `SessionModelID`, `SessionModelName`, `Prompt`, `TemperatureCoefficient`, `TopPCoefficient`, `SystemStatus`, `CreateTime`, `LastUpdateTime`) VALUES ('020db83fc1d39990448074b97e938b52', 'AgentBrook系统使用说明', '21', NULL, NULL, '22', '客服', 'AgentBrook系统使用说明\n包括系统开发的目的，背景，描述，支持的开发语言、数据库、设计结构、系统模块、部署环境的介绍，以及各个模块的操作说明，系统使用的注意事项。', 13, 'UCloud(Qwen/Qwen3-32B)', '你是一个很棒的AgentBrook系统使用说明介绍专员，可以将知识库中关于AgentBrook的知识与用户的问题匹配，并合理的回答用户。', 50.00, 80.00, 1, '2024-08-23 20:21:05', '2024-08-23 20:20:53');
