INSERT INTO `tb_agent_info` (`AgentID`, `Name`, `AICON`, `MemberID`, `MemberName`, `DicIDList`, `DicNameList`, `Description`, `SessionModelID`, `SessionModelName`, `Prompt`, `TemperatureCoefficient`, `TopPCoefficient`, `SystemStatus`, `CreateTime`, `LastUpdateTime`) VALUES ('7348ec5f0be249912aba2b4ea5fab1ce', '图片处理', '#', NULL, NULL, '23', '助理', '图片处理', 13, 'UCloud(Qwen/Qwen3-32B)', '图片处理', 0.00, 0.00, 1, '2026-04-27 10:49:56', '2026-04-27 10:49:15');
