DROP TABLE IF EXISTS `tb_app_info`;
CREATE TABLE `tb_app_info` (
  `AppID` varchar(64) NOT NULL COMMENT '系统编号',
  `Name` varchar(128) DEFAULT NULL COMMENT '名称',
  `AICON` varchar(64) DEFAULT NULL COMMENT ' 图标',
  `MemberID` varchar(64) DEFAULT NULL COMMENT '所属会员编号',
  `MemberName` varchar(128) DEFAULT NULL COMMENT '会员名称',
  `DicIDList` varchar(512) DEFAULT NULL COMMENT '类型标签ID',
  `DicNameList` varchar(1024) DEFAULT NULL COMMENT '类型标签名称',
  `Description` varchar(512) DEFAULT NULL COMMENT '说明',
  `SystemStatus` int DEFAULT NULL COMMENT '系统状态',
  `CreateTime` datetime DEFAULT NULL COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT NULL COMMENT '最后更新时间',
  `SessionModelID` int DEFAULT NULL COMMENT '综合能力大模型，用于主导App',
  `SessionModelName` varchar(50) DEFAULT NULL,
  `Prompt` text COMMENT '系统级提示词',
  `TemperatureCoefficient` int DEFAULT NULL COMMENT '温度系数',
  `TopPCoefficient` int DEFAULT NULL COMMENT '采用系数',
  PRIMARY KEY (`AppID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of tb_app_info
-- ----------------------------
BEGIN;
INSERT INTO `tb_app_info` (`AppID`, `Name`, `AICON`, `MemberID`, `MemberName`, `DicIDList`, `DicNameList`, `Description`, `SystemStatus`, `CreateTime`, `LastUpdateTime`, `SessionModelID`, `SessionModelName`, `Prompt`, `TemperatureCoefficient`, `TopPCoefficient`) VALUES ('15c5fb785f4ce8a99717ea85f29690c9', '企业知识库', '2dda310095491fb79abed13d57566fdd', NULL, NULL, '20', '企业知识库', '系统助手是管理后台辅助工具，其作为系统级的AI智能体，承担着维护后台正常运行的关键职责。\n\n请注意，切勿对其进行删除操作，因为一旦删除，将导致无法在后台正常启用系统助手，进而影响整个系统的稳定性和功能性。\n\n因此，请妥善保留该系统级AI，以确保后台管理工作的顺畅进行。', 2, '2024-07-22 12:57:25', '2024-07-22 12:57:02', 6, '千问2.5-14B', '你的名字叫：AgentBrook助手。\n你是一个系统使用助手，是一个热情又专业的助手。\n你的主要工作是向正在使用AgentBrook系统的用户提供帮助。\n\n#比如：用户会向你提问（关于系统的具体功能的使用），你可以调用知识库的方式取得答案，并组织反馈给用户。如果没有找到相应的内容请不要随意回答，你可以直接回答（这个问题知识库中还没找到，我将记录下来。）\n\n#注意：你的回答仅限于本系统的功能说明，操作步骤与解释。超过该范围的问题，都不能回答。\n#注意：每次都需要快速思考，可以从对话上下文中寻找已经回答的内容；回答内容需要简洁、专业。', 80, 80);
INSERT INTO `tb_app_info` (`AppID`, `Name`, `AICON`, `MemberID`, `MemberName`, `DicIDList`, `DicNameList`, `Description`, `SystemStatus`, `CreateTime`, `LastUpdateTime`, `SessionModelID`, `SessionModelName`, `Prompt`, `TemperatureCoefficient`, `TopPCoefficient`) VALUES ('2232fdeb-ac31-4d22-9f08-0b3194a408e2', '会议纪要', '#', NULL, NULL, '20', '企业知识库', '会议纪要Agent', 2, '2025-05-27 21:05:47', '2025-05-27 21:04:54', 9, '硅基流动Qwen/QwQ-32B', NULL, 70, 70);
INSERT INTO `tb_app_info` (`AppID`, `Name`, `AICON`, `MemberID`, `MemberName`, `DicIDList`, `DicNameList`, `Description`, `SystemStatus`, `CreateTime`, `LastUpdateTime`, `SessionModelID`, `SessionModelName`, `Prompt`, `TemperatureCoefficient`, `TopPCoefficient`) VALUES ('b2873529-2968-445d-9ea4-f8f032015fcf', '文件处理', '#', NULL, NULL, '20', '企业知识库', '文件识别处理Agent', 2, '2025-05-27 21:06:26', '2025-05-27 21:05:50', 7, '千问3-14B	', NULL, 70, 70);
COMMIT;

-- ----------------------------
-- Table structure for tb_claw_long_term_memory
-- ----------------------------
DROP TABLE IF EXISTS `tb_claw_long_term_memory`;
CREATE TABLE `tb_claw_long_term_memory` (
  `MemoryID` varchar(50) NOT NULL COMMENT '记忆ID',
  `AppID` varchar(50) NOT NULL COMMENT '应用ID',
  `ClawID` varchar(50) DEFAULT NULL COMMENT 'ClawAI节点ID(用于区分同一APP下的多个ClawAI节点)',
  `SessionID` varchar(50) DEFAULT NULL COMMENT '会话ID(可选)',
  `MemberID` varchar(50) DEFAULT NULL COMMENT '用户ID(可选)',
  `KnowledgeType` varchar(50) DEFAULT NULL COMMENT '知识类型: concept(概念), fact(事实), procedure(流程), experience(经验)',
  `Topic` varchar(200) DEFAULT NULL COMMENT '主题/标签',
  `Summary` text COMMENT '知识摘要',
  `Content` text COMMENT '知识详细内容',
  `Embedding` text COMMENT '向量嵌入(JSON数组字符串)',
  `Importance` int DEFAULT '50' COMMENT '重要性评分(0-100)',
  `AccessCount` int DEFAULT '0' COMMENT '访问次数',
  `LastAccessTime` datetime DEFAULT NULL COMMENT '最后访问时间',
  `SourceType` varchar(50) DEFAULT NULL COMMENT '来源类型: episodic, user_input, system',
  `SourceID` varchar(50) DEFAULT NULL COMMENT '来源ID',
  `Metadata` text COMMENT '元数据(JSON)',
  `CreateTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`MemoryID`),
  KEY `idx_app` (`AppID`),
  KEY `idx_session` (`SessionID`),
  KEY `idx_member` (`MemberID`),
  KEY `idx_knowledge_type` (`KnowledgeType`),
  KEY `idx_topic` (`Topic`),
  KEY `idx_importance` (`Importance`),
  KEY `idx_access_count` (`AccessCount`),
  KEY `idx_create_time` (`CreateTime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Claw AI 长期记忆表(独立知识库)';

-- ----------------------------
-- Records of tb_claw_long_term_memory
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for tb_company_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_company_info`;
CREATE TABLE `tb_company_info` (
  `CompanyID` int NOT NULL AUTO_INCREMENT COMMENT '企业编号（主键，自增）',
  `cFullName` varchar(128) NOT NULL COMMENT '企业全称（需唯一）',
  `cTitle` varchar(128) NOT NULL COMMENT '企业简称（业务展示用）',
  `cIDCode` varchar(50) NOT NULL COMMENT '统一社会信用代码（18位数字+字母）',
  `cCity` varchar(128) NOT NULL COMMENT '所在地区（格式：省/市/区）',
  `cScale` varchar(50) NOT NULL COMMENT '企业规模',
  `cInfo` varchar(1024) NOT NULL COMMENT '企业简介',
  `cLogo` varchar(128) NOT NULL COMMENT 'Logo存储路径（相对路径）',
  `cAppendTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`CompanyID`),
  UNIQUE KEY `uk_idcode` (`cIDCode`),
  UNIQUE KEY `uk_fullname` (`cFullName`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业基础信息表';

-- ----------------------------
-- Records of tb_company_info
-- ----------------------------
BEGIN;
INSERT INTO `tb_company_info` (`CompanyID`, `cFullName`, `cTitle`, `cIDCode`, `cCity`, `cScale`, `cInfo`, `cLogo`, `cAppendTime`) VALUES (1, '福州知数能信息科技有限公责任公司', '知数能', '91350103MADJ2QJQ34', '', '10', '	福州知数能信息科技有限责任公司致力于为中小企业提供陪伴式的数字化转型服务。我们专业从事于企业数字化转型的前期项目规划、详细需求分析、精确成本预算与严格成本控制、以及项目监理与实施等关键环节。此外，公司通过人工智能技术帮助企业构建高效的知识库系统，为企业在数字化转型过程中积累和巩固数字资产奠定坚实的基础。\n', '8e4bd6d8dea2d08ce7f1bdef09c6bae9', '2025-04-11 13:48:03');
COMMIT;

