  `Type` varchar(128) NOT NULL COMMENT '文件类型',
  `ParserConfig` json NOT NULL COMMENT '存储转换时的配置信息',
  `DataCount` int NOT NULL DEFAULT '0' COMMENT '分块数',
  `CreateTime` datetime NOT NULL COMMENT '创建时间',
  `SystemStatus` int NOT NULL COMMENT '系统状态，屏蔽=-1，分析失败=-2，等待分析=0，分析完成=1',
  PRIMARY KEY (`FileID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库文件信息';


-- ----------------------------
-- Table structure for tb_knowledge_base_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_knowledge_base_info`;
CREATE TABLE `tb_knowledge_base_info` (
  `KnowledgeBaseID` varchar(64) NOT NULL COMMENT '知识库编号',
  `Name` varchar(128) NOT NULL COMMENT '名称',
  `DicIDList` varchar(512) DEFAULT NULL COMMENT '类型标签ID',
  `DicNameList` varchar(1024) DEFAULT NULL COMMENT '类型标签名称',
  `Description` varchar(512) DEFAULT NULL COMMENT '说明',
  `PreprocessModelID` int DEFAULT NULL COMMENT '预处理模型',
  `PreprocessModelName` varchar(128) DEFAULT NULL COMMENT '预处理模型名称',
  `VectorModelID` int DEFAULT NULL COMMENT '向量模型',
  `VectorModelName` varchar(128) DEFAULT NULL COMMENT '向量模型名称',
  `ParagraphSlice` int DEFAULT NULL COMMENT '段落切片（token）',
  `LineSliceCount` int DEFAULT NULL COMMENT '行切片数（token）',
  `OverlapSection` int DEFAULT NULL COMMENT '重叠部分（token）',
  `SystemStatus` int NOT NULL COMMENT '系统状态',
  `MemberID` varchar(64) DEFAULT NULL COMMENT '所属用户编号',
  `ChargeType` int NOT NULL COMMENT '收费类型',
  `CreateTime` datetime DEFAULT NULL COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT NULL COMMENT '最后更新时间',
  `EnableImageProcessing` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用图片处理',
  `VisionModelID` int NOT NULL DEFAULT '0' COMMENT '视觉大模型ID',
  `VisionModelName` varchar(128) NOT NULL DEFAULT '' COMMENT '视觉大模型名称',
  PRIMARY KEY (`KnowledgeBaseID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

