-- Table structure for tb_planning_revision
-- ----------------------------
DROP TABLE IF EXISTS `tb_planning_revision`;
CREATE TABLE `tb_planning_revision` (
  `RevisionID` varchar(50) NOT NULL COMMENT '修订ID',
  `PlanningID` varchar(50) NOT NULL COMMENT '规划ID',
  `RevisionVersion` int NOT NULL COMMENT '修订版本号',
  `RevisionReason` text COMMENT '修订原因',
  `OldPlanningContent` text COMMENT '修订前的规划内容(JSON)',
  `NewPlanningContent` text COMMENT '修订后的规划内容(JSON)',
  `RevisionTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '修订时间',
  PRIMARY KEY (`RevisionID`),
  KEY `idx_planning` (`PlanningID`),
  KEY `idx_version` (`PlanningID`,`RevisionVersion`),
  CONSTRAINT `tb_planning_revision_ibfk_1` FOREIGN KEY (`PlanningID`) REFERENCES `tb_task_planning` (`PlanningID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Claw AI 规划修订历史表';

