-- ----------------------------
-- Table structure for tb_staff_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_staff_info`;
CREATE TABLE `tb_staff_info` (
  `StaffID` int NOT NULL AUTO_INCREMENT COMMENT '员工系统编号（主键，自增）',
  `sCode` varchar(50) NOT NULL COMMENT '员工编号（业务唯一）',
  `sName` varchar(50) NOT NULL COMMENT '员工姓名',
  `sTitle` varchar(50) DEFAULT NULL COMMENT '职位头衔',
  `DepartmentID` int NOT NULL COMMENT '所属部门编号（外键关联tb_Department_Info.DepartmentID）',
  `dName` varchar(50) NOT NULL COMMENT '所属部门名称（冗余存储）',
  `sEntryTime` datetime NOT NULL COMMENT '入职时间',
  `sState` int NOT NULL COMMENT '系统状态（0=在职，1=离职，2=停职）',
  `sAppendTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `sEmail` varchar(50) NOT NULL COMMENT '企业邮箱',
  `sPhone` varchar(50) NOT NULL COMMENT '手机号（带国际区号）',
  `MemberID` varchar(64) NOT NULL COMMENT '关联会员表ID',
  `UserID` int DEFAULT NULL COMMENT '关联UserID',
  PRIMARY KEY (`StaffID`),
  UNIQUE KEY `uk_scode` (`sCode`),
  UNIQUE KEY `uk_email` (`sEmail`),
  KEY `fk_department` (`DepartmentID`),
  CONSTRAINT `fk_department` FOREIGN KEY (`DepartmentID`) REFERENCES `tb_department_info` (`DepartmentID`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='员工信息表';

-- ----------------------------
-- Records of tb_staff_info
-- ----------------------------
BEGIN;
