COMMIT;

-- ----------------------------
-- Table structure for tb_task_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_task_info`;
CREATE TABLE `tb_task_info` (
  `TaskID` varchar(64) NOT NULL COMMENT '对话记录编号，唯一标识每个任务，自动生成',
  `TaskType` int NOT NULL COMMENT '任务类型，表示不同种类的异步操作',
  `TaskConfig` json NOT NULL COMMENT '任务参数，以JSON格式存储，定义任务配置参数',
  `CreateTime` datetime NOT NULL COMMENT '创建时间，记录任务的创建时间',
  `UpdateTime` datetime NOT NULL COMMENT '最后更新时间，记录任务的最后更新时间',
  `State` int NOT NULL COMMENT '任务状态，0=等待中，1=处理中，2=完成，-1=失败',
  `Results` json DEFAULT NULL COMMENT '处理结果，以JSON格式存储任务处理结果',
  `LoopType` int NOT NULL DEFAULT '0' COMMENT '重复周期类型\n0=不重复\n1=秒\n2=天\n3=每周几\n4=每月第几天 ',
  `IntervalValue` json DEFAULT NULL COMMENT 'IntervalValue不等于0时启用',
  `RepeatValue` int NOT NULL DEFAULT '0' COMMENT '默认=0，无限次\r\nInterval等于0时表示任务失败重试次数',
  `RedoCount` int NOT NULL DEFAULT '0',
  `FromTaskID` varchar(64) DEFAULT NULL COMMENT '下发任务标识',
  `FromMainTaskID` varchar(64) DEFAULT '' COMMENT '主任务标识',
  `WorkflowID` varchar(64) DEFAULT NULL COMMENT '工作流ID',
  `SessionID` varchar(64) DEFAULT NULL COMMENT '回话ID',
  `ProcessesID` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '任务ID',
  PRIMARY KEY (`TaskID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='异步任务信息表，支持任务创建、状态更新以及结果存储';

-- ----------------------------
-- Records of tb_task_info
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for tb_task_planning
-- ----------------------------
DROP TABLE IF EXISTS `tb_task_planning`;
CREATE TABLE `tb_task_planning` (
  `PlanningID` varchar(50) NOT NULL COMMENT '规划ID',
  `AppID` varchar(50) NOT NULL COMMENT '应用ID',
  `SessionID` varchar(50) NOT NULL COMMENT '会话ID',
  `MemberID` varchar(50) NOT NULL COMMENT '用户ID',
  `NodeID` varchar(50) NOT NULL COMMENT '节点ID',
  `ProcessesID` varchar(50) NOT NULL COMMENT '流程ID',
  `OriginalTask` text NOT NULL COMMENT '原始任务描述',
  `PlanningStatus` varchar(20) DEFAULT 'Planning' COMMENT '规划状态: Planning, Executing, Completed, Failed, Paused',
  `CurrentStepIndex` int DEFAULT '0' COMMENT '当前执行到第几步',
  `TotalSteps` int DEFAULT '0' COMMENT '总步骤数',
  `Strategy` varchar(100) DEFAULT NULL COMMENT '规划策略',
  `Confidence` int DEFAULT '0' COMMENT '规划置信度(0-100)',
  `EstimatedDuration` int DEFAULT '0' COMMENT '预估总耗时(秒)',
  `ActualDuration` int DEFAULT '0' COMMENT '实际耗时(秒)',
  `RevisionCount` int DEFAULT '0' COMMENT '修订次数',
  `CreateTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`PlanningID`),
  KEY `idx_session` (`SessionID`),
  KEY `idx_member` (`MemberID`),
  KEY `idx_app` (`AppID`),
  KEY `idx_status` (`PlanningStatus`),
  KEY `idx_create_time` (`CreateTime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Claw AI 任务规划主表';

-- ----------------------------
-- Records of tb_task_planning
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for tb_task_step
-- ----------------------------
DROP TABLE IF EXISTS `tb_task_step`;
CREATE TABLE `tb_task_step` (
  `StepID` varchar(50) NOT NULL COMMENT '步骤ID',
  `PlanningID` varchar(50) NOT NULL COMMENT '规划ID',
  `StepIndex` int NOT NULL COMMENT '步骤序号',
  `StepDescription` text NOT NULL COMMENT '步骤描述',
  `StepType` varchar(50) DEFAULT 'AgentCall' COMMENT '步骤类型: AgentCall, LLMReasoning, DataCollection, Validation, Synthesis',
  `AssignedWorkflowIds` text,
  `StepStatus` varchar(20) DEFAULT 'Pending' COMMENT '步骤状态: Pending, Executing, Completed, Failed, Skipped',
  `DependsOnStepIds` text COMMENT '依赖的步骤ID列表(JSON数组)',
  `StepInputs` text COMMENT '步骤输入参数(JSON数组)',
  `ExpectedOutput` text COMMENT '预期输出',
  `ActualOutput` text COMMENT '实际输出',
  `ExecutionResult` text COMMENT '执行结果',
  `StartTime` datetime DEFAULT NULL COMMENT '执行开始时间',
  `EndTime` datetime DEFAULT NULL COMMENT '执行结束时间',
  `RetryCount` int DEFAULT '0' COMMENT '重试次数',
  `QualityScore` int DEFAULT NULL COMMENT '质量评分(0-100)',
  `ErrorMessage` text COMMENT '错误信息',
  `CreateTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`StepID`),
  KEY `idx_planning` (`PlanningID`),
  KEY `idx_status` (`StepStatus`),
  KEY `idx_step_index` (`PlanningID`,`StepIndex`),
  CONSTRAINT `tb_task_step_ibfk_1` FOREIGN KEY (`PlanningID`) REFERENCES `tb_task_planning` (`PlanningID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Claw AI 任务步骤表';

-- ----------------------------
-- Records of tb_task_step
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for tb_user_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_user_info`;
CREATE TABLE `tb_user_info` (
  `UserID` int NOT NULL AUTO_INCREMENT COMMENT '用户编号',
  `uName` varchar(50) DEFAULT NULL COMMENT '用户名',
  `uPWD` varchar(32) DEFAULT NULL COMMENT '密码',
  `PermissionCode` varchar(2048) DEFAULT NULL COMMENT '权限代码',
  `uState` int NOT NULL COMMENT '系统状态',
  `uAppendTime` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`UserID`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of tb_user_info
