-- ----------------------------
-- Table structure for tb_workflow_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_workflow_info`;
CREATE TABLE `tb_workflow_info` (
  `WorkflowID` varchar(64) NOT NULL COMMENT '系统编号，唯一',
  `MainType` int DEFAULT NULL COMMENT '挂载主体类型，APP=1，Agent=2',
  `MainID` varchar(64) DEFAULT NULL COMMENT '挂载主体ID',
  `WorkflowName` varchar(128) DEFAULT NULL COMMENT '名称',
  `Description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '说明',
  `SystemStatus` int DEFAULT NULL COMMENT '系统状态，屏蔽=-1，未发布=0，发布=1',
  `CreateTime` datetime DEFAULT NULL COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT NULL COMMENT '最后更新时间',
  `Config` json DEFAULT NULL COMMENT '动态配置信息',
  PRIMARY KEY (`WorkflowID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of tb_workflow_info
-- ----------------------------
BEGIN;
INSERT INTO `tb_workflow_info` (`WorkflowID`, `MainType`, `MainID`, `WorkflowName`, `Description`, `SystemStatus`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('09b837bf-ca2e-4951-b8b1-7a254a9fbb0c', 2, '020db83fc1d39990448074b97e938b52', 'AgentBrook使用说明 助理 工作流', '可以通过这个工作流检索关于AgentBrook的部署、使用、功能、注意事项等。', 1, '2025-08-19 13:09:27', '2026-05-11 13:33:52', NULL);
