INSERT INTO `tb_workflow_info` (`WorkflowID`, `MainType`, `MainID`, `WorkflowName`, `Description`, `SystemStatus`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('6c8d595b-3494-4052-b486-aacec4806215', 1, '15c5fb785f4ce8a99717ea85f29690c9', '应用 工作流', '【功能档案（Profile）】\n- **Name**: 企业知识库管理系统\n- **Description**: 一个用于构建、管理与查询企业内部知识库的系统化工具，支持结构化知识存储、检索与维护。\n- **Category**: 知识管理 / 企业应用\n', 1, '2025-08-21 10:28:25', '2026-05-11 11:03:52', NULL);
INSERT INTO `tb_workflow_info` (`WorkflowID`, `MainType`, `MainID`, `WorkflowName`, `Description`, `SystemStatus`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('a9116ccf-798d-4127-8303-eac56fa79fa2', 2, '5897afa60287cb50a619b9f0ae672ba4', '闲聊 情绪价值 助理 工作流', '【技能档案（Profile）】\n- **Name**: EmotionalSupportAgent 中文名：情绪支持客服流程\n- **Description**: 提供情绪安抚、倾听与心理支持的客服流程，用于处理用户在情感或心理层面的需求。\n- **Version**: 1.0\n- **Category**: 客户服务 / 情绪支持\n', 1, '2026-03-26 15:26:19', '2026-04-27 17:42:54', NULL);
