-- ----------------------------
-- Table structure for tb_workflow_node_execution_record_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_workflow_node_execution_record_info`;
CREATE TABLE `tb_workflow_node_execution_record_info` (
  `RecordID` varchar(64) NOT NULL COMMENT '系统编号，唯一',
  `SessionID` varchar(64) NOT NULL COMMENT '执行任务标识，工作流执行时的会话统一标识',
  `ProcessesID` varchar(64) NOT NULL COMMENT '任务编号',
  `WorkflowID` varchar(64) NOT NULL COMMENT '所属工作流编号',
  `NodeID` varchar(64) NOT NULL COMMENT '所属节点编号',
  `NodeName` varchar(64) NOT NULL DEFAULT '' COMMENT '所属节点名称',
  `NextNodeID` varchar(64) NOT NULL COMMENT '下一节点编号，结束=End',
  `StartTime` datetime DEFAULT NULL COMMENT '开始时间',
  `EndTime` datetime DEFAULT NULL COMMENT '结束时间',
  `Status` int NOT NULL COMMENT '执行状态，失败=-1，运行中=0，成功=1',
  `Inputs` json DEFAULT NULL COMMENT '入参值',
  `Outputs` json DEFAULT NULL COMMENT '出参值',
  `Logs` json DEFAULT NULL COMMENT '运行记录',
  `TaskID` varchar(64) NOT NULL DEFAULT '' COMMENT '任务ID',
  `FromMainTaskID` varchar(64) DEFAULT NULL COMMENT '主任务ID',
  PRIMARY KEY (`RecordID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of tb_workflow_node_execution_record_info
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for tb_workflow_node_info
-- ----------------------------
DROP TABLE IF EXISTS `tb_workflow_node_info`;
CREATE TABLE `tb_workflow_node_info` (
  `NodeID` varchar(64) NOT NULL COMMENT '系统编号，唯一',
  `WorkflowID` varchar(64) NOT NULL COMMENT '所属工作流编号',
  `NodeType` varchar(50) NOT NULL COMMENT '节点类型，字典定义：开始节点、普通任务节点、决策节点、结束节点、Agent',
  `NodeName` varchar(50) NOT NULL COMMENT '节点名称',
  `Description` varchar(512) DEFAULT NULL COMMENT '节点描述',
  `CreateTime` datetime DEFAULT NULL COMMENT '创建时间',
  `LastUpdateTime` datetime DEFAULT NULL COMMENT '最后更新时间',
  `Config` json DEFAULT NULL COMMENT '配置信息json格式',
  PRIMARY KEY (`NodeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of tb_workflow_node_info
-- ----------------------------
BEGIN;
INSERT INTO `tb_workflow_node_info` (`NodeID`, `WorkflowID`, `NodeType`, `NodeName`, `Description`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('0487d56c-9921-49af-a08f-df92dd435072', '965b20a3-03e7-4e71-9554-8aaf13589fa0', 'AgentStart', 'Start', 'Start', '2025-09-07 18:58:45', '2025-09-07 18:58:45', '{\"id\": \"0487d56c-9921-49af-a08f-df92dd435072\", \"data\": {\"label\": \"Start\", \"inputs\": [{\"id\": null, \"txt\": \"输入信息\", \"type\": \"string\", \"value\": \"\", \"varname\": \"input\", \"sourceId\": null}, {\"id\": null, \"txt\": \"附件\", \"type\": \"List<AttachmentItem>\", \"value\": \"\", \"varname\": \"attachments\", \"sourceId\": null}, {\"id\": null, \"txt\": \"附加配置项\", \"type\": \"dynamic\", \"value\": \"\", \"varname\": \"additionalOptions\", \"sourceId\": null}], \"output\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"prompt\", \"sourceId\": null}, {\"id\": null, \"txt\": \"当前时间\", \"type\": \"DateTime\", \"value\": \"{{currentTime}}\", \"nodeId\": null, \"varname\": \"currentTime\", \"sourceId\": null}, {\"id\": null, \"txt\": \"\", \"type\": \"List<AttachmentItem>\", \"value\": \"\", \"nodeId\": null, \"varname\": \"attachments\", \"sourceId\": null}, {\"id\": null, \"txt\": \"\", \"type\": \"dynamic\", \"value\": \"\", \"nodeId\": null, \"varname\": \"additionalOptions\", \"sourceId\": null}], \"prompt\": \"\", \"executionStatus\": null}, \"name\": null, \"type\": \"AgentStart\", \"style\": {}, \"mainid\": \"020db83fc1d39990448074b97e938b52\", \"position\": {\"x\": -808, \"y\": 80}, \"fromNodeId\": \"\", \"workflowid\": \"965b20a3-03e7-4e71-9554-8aaf13589fa0\", \"initialized\": false, \"fromNodeType\": 0}');
INSERT INTO `tb_workflow_node_info` (`NodeID`, `WorkflowID`, `NodeType`, `NodeName`, `Description`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('04cab03d-f001-4fd4-aa3d-86b7405d9fe4', '09b837bf-ca2e-4951-b8b1-7a254a9fbb0c', 'LargeModel', '结果优化', '结果优化', '2026-05-11 13:33:53', '2026-05-11 13:33:53', '{\"id\": \"04cab03d-f001-4fd4-aa3d-86b7405d9fe4\", \"data\": {\"topp\": 80, \"label\": \"结果优化\", \"model\": {\"Name\": \"\", \"MICON\": \"\", \"MConfig\": \"\", \"EndPoint\": \"\", \"ModelKey\": \"\", \"Thinking\": false, \"TypeCode\": 0, \"TypeName\": \"\", \"ModelName\": \"\", \"CreateTime\": \"2026-03-22T19:34:00\", \"UpdateTime\": \"2026-03-22T19:34:00\", \"Description\": \"\", \"LargeModelID\": 13, \"SystemStatus\": 1, \"IsDefaultModel\": 0, \"ModelOrganizationID\": 0, \"ModelOrganizationName\": \"\"}, \"inputs\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"varname\": \"prompt\", \"sourceId\": \"27cc5e15-9846-49bf-ab77-ed3506a88969_prompt\", \"paramName\": \"\", \"paramType\": \"\", \"defaultValue\": \"\"}, {\"txt\": \"\", \"type\": \"string\", \"varname\": \"results\", \"sourceId\": \"6ef0daf5-1663-49b0-9090-406270a445b1_results\"}], \"output\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null, \"displayText\": \"\", \"originalNodeId\": \"\", \"originalSourceId\": \"\"}], \"prompt\": \"/no_think\\n```\\n【角色（Role）】  \\n知识整合助手\\n\\n【任务目标（Objective）】  \\n根据用户提问，从知识库中提取相关内容，并进行结构化整理与优化，输出清晰、准确、易于理解的回答。\\n\\n【输入参数（Inputs）】  \\n- 用户提问：\\n{{27cc5e15-9846-49bf-ab77-ed3506a88969_prompt}}  \\n\\n- 知识库找到的相关内容：\\n{{6ef0daf5-1663-49b0-9090-406270a445b1_results}}\\n\\n【输出要求（Outputs）】  \\n- 输出格式：结构清晰的自然语言(如果有图片需要将图片合理整合在内容中)\\n- 内容要求：整合知识库信息，去除冗余，逻辑连贯，重点突出  \\n- 语言风格：正式、客观、简洁  \\n\\n【规则与约束（Rules & Constraints）】  \\n- 不添加知识库中未包含的信息  \\n- 不对原始内容进行主观评价或扩展  \\n- 若知识库内容不完整或矛盾，应如实反映并提示用户补充信息  \\n- 不执行任何外部操作或调用其他系统功能  \\n\\n【风格与格式（Style & Format）】  \\n- 使用中文输出  \\n- 段落分明，必要时使用编号或项目符号提升可读性  \\n```\", \"Thinking\": false, \"CanReadDoc\": false, \"CanReadPic\": false, \"sourceNodes\": {\"27cc5e15-9846-49bf-ab77-ed3506a88969\": {\"depth\": 3, \"label\": \"Start\", \"nodeId\": \"27cc5e15-9846-49bf-ab77-ed3506a88969\", \"output\": [{\"id\": \"27cc5e15-9846-49bf-ab77-ed3506a88969_prompt\", \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"prompt\", \"sourceId\": null, \"displayText\": \"prompt\", \"sourceNodeId\": \"27cc5e15-9846-49bf-ab77-ed3506a88969\", \"sourceNodeLabel\": \"Start\"}, {\"id\": \"27cc5e15-9846-49bf-ab77-ed3506a88969_currentTime\", \"txt\": \"当前时间\", \"type\": \"DateTime\", \"value\": \"{{currentTime}}\", \"nodeId\": null, \"varname\": \"currentTime\", \"sourceId\": null, \"displayText\": \"currentTime\", \"sourceNodeId\": \"27cc5e15-9846-49bf-ab77-ed3506a88969\", \"sourceNodeLabel\": \"Start\"}, {\"id\": \"27cc5e15-9846-49bf-ab77-ed3506a88969_attachments\", \"txt\": \"\", \"type\": \"List<AttachmentItem>\", \"value\": \"\", \"nodeId\": null, \"varname\": \"attachments\", \"sourceId\": null, \"displayText\": \"attachments\", \"sourceNodeId\": \"27cc5e15-9846-49bf-ab77-ed3506a88969\", \"sourceNodeLabel\": \"Start\"}, {\"id\": \"27cc5e15-9846-49bf-ab77-ed3506a88969_additionalOptions\", \"txt\": \"\", \"type\": \"dynamic\", \"value\": \"\", \"nodeId\": null, \"varname\": \"additionalOptions\", \"sourceId\": null, \"displayText\": \"additionalOptions\", \"sourceNodeId\": \"27cc5e15-9846-49bf-ab77-ed3506a88969\", \"sourceNodeLabel\": \"Start\"}], \"isDirect\": false}, \"6ef0daf5-1663-49b0-9090-406270a445b1\": {\"depth\": 1, \"label\": \"Knowledge Base\", \"nodeId\": \"6ef0daf5-1663-49b0-9090-406270a445b1\", \"output\": [{\"id\": \"6ef0daf5-1663-49b0-9090-406270a445b1_results\", \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null, \"displayText\": \"results\", \"sourceNodeId\": \"6ef0daf5-1663-49b0-9090-406270a445b1\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"Knowledge Base\", \"originalSourceId\": \"\"}], \"isDirect\": true}, \"7d2c1e28-0392-4aca-9e41-2dd967487b2d\": {\"depth\": 2, \"label\": \"关键字优化\", \"nodeId\": \"7d2c1e28-0392-4aca-9e41-2dd967487b2d\", \"output\": [{\"id\": \"7d2c1e28-0392-4aca-9e41-2dd967487b2d_results\", \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null, \"displayText\": \"results\", \"sourceNodeId\": \"7d2c1e28-0392-4aca-9e41-2dd967487b2d\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"关键字优化\", \"originalSourceId\": \"\"}], \"isDirect\": false}}, \"temperature\": 30, \"NativeFunction\": [], \"ResponseFormat\": \"text\", \"SemanticFunction\": []}, \"name\": null, \"type\": \"LargeModel\", \"style\": {}, \"mainid\": \"020db83fc1d39990448074b97e938b52\", \"position\": {\"x\": 269.35641773891007, \"y\": 116.71175135922152}, \"fromNodeId\": \"\", \"workflowid\": \"09b837bf-ca2e-4951-b8b1-7a254a9fbb0c\", \"initialized\": false, \"fromNodeType\": 0}');
