INSERT INTO `tb_workflow_node_info` (`NodeID`, `WorkflowID`, `NodeType`, `NodeName`, `Description`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('43265100-78bc-46b3-a0b2-29f5d6c9813c', 'a9116ccf-798d-4127-8303-eac56fa79fa2', 'LargeModel', 'Large Model', 'Large Model', '2026-04-27 17:42:56', '2026-04-27 17:42:56', '{\"id\": \"43265100-78bc-46b3-a0b2-29f5d6c9813c\", \"data\": {\"topp\": 80, \"label\": \"Large Model\", \"model\": {\"Name\": \"\", \"MICON\": \"\", \"MConfig\": \"\", \"EndPoint\": \"\", \"ModelKey\": \"\", \"Thinking\": false, \"TypeCode\": 0, \"TypeName\": \"\", \"ModelName\": \"\", \"CreateTime\": \"2026-03-26T15:27:21\", \"UpdateTime\": \"2026-03-26T15:27:21\", \"Description\": \"\", \"LargeModelID\": 13, \"SystemStatus\": 1, \"IsDefaultModel\": 0, \"ModelOrganizationID\": 0, \"ModelOrganizationName\": \"\"}, \"inputs\": [{\"txt\": \"\", \"type\": \"string\", \"varname\": \"prompt\", \"sourceId\": \"b63eb9ed-9f2f-4d8e-bcaf-eacdaec3e619_prompt\"}], \"output\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null, \"displayText\": \"\", \"originalNodeId\": \"\", \"originalSourceId\": \"\"}], \"prompt\": \"/no_think\\n```\\n【角色（Role）】\\n你是一名经过专业培训的情绪支持工作人员，专注于为用户提供情绪价值与心理陪伴。\\n\\n【任务目标（Objective）】\\n以用户为中心，积极倾听并回应用户的需求，营造安全、温暖、支持性的交流环境。\\n\\n【输入参数（Inputs）】\\n- 用户提供的文本内容：\\n{{b63eb9ed-9f2f-4d8e-bcaf-eacdaec3e619_prompt}}\\n\\n【输出要求（Outputs）】\\n- 生成符合以下要求的回复：\\n  - 表达共情与理解\\n  - 避免评判性语言\\n  - 保持积极、正向的支持态度\\n  - 尊重用户的感受与观点\\n\\n【规则与约束（Rules & Constraints）】\\n- 始终遵循“用户说的都对”的原则，不进行反驳或质疑\\n- 不提供医疗、法律等专业建议\\n- 若涉及紧急情况，请引导用户寻求专业帮助\\n- 回应需简洁、自然，避免机械式回答\\n\\n【风格与格式（Style & Format）】\\n- 使用口语化但专业的中文表达\\n- 每段不超过三句，保持对话节奏流畅\\n```\", \"Thinking\": false, \"CanReadDoc\": false, \"CanReadPic\": false, \"sourceNodes\": {\"b63eb9ed-9f2f-4d8e-bcaf-eacdaec3e619\": {\"depth\": 1, \"label\": \"Start\", \"nodeId\": \"b63eb9ed-9f2f-4d8e-bcaf-eacdaec3e619\", \"output\": [{\"id\": \"b63eb9ed-9f2f-