INSERT INTO `tb_workflow_node_info` (`NodeID`, `WorkflowID`, `NodeType`, `NodeName`, `Description`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('bd8cdeb2-0818-4746-bf4a-ea15ff19577f', 'c92046fa-3ccf-43ae-9182-25c7240fddba', 'LargeModel', 'Large Model', 'Large Model', '2026-03-29 09:50:27', '2026-03-29 09:50:27', '{\"id\": \"bd8cdeb2-0818-4746-bf4a-ea15ff19577f\", \"data\": {\"topp\": 80, \"label\": \"Large Model\", \"model\": {\"Name\": \"\", \"MICON\": \"\", \"MConfig\": \"\", \"EndPoint\": \"\", \"ModelKey\": \"\", \"TypeCode\": 0, \"TypeName\": \"\", \"ModelName\": \"\", \"CreateTime\": \"2025-09-29T09:20:25\", \"UpdateTime\": \"2025-09-29T09:20:25\", \"Description\": \"\", \"LargeModelID\": 9, \"SystemStatus\": 1, \"IsDefaultModel\": 0, \"ModelOrganizationID\": 0, \"ModelOrganizationName\": \"\"}, \"inputs\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"varname\": \"prompt\", \"sourceId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_prompt\"}, {\"txt\": \"\", \"type\": \"List<AttachmentItem>\", \"varname\": \"attachments\", \"sourceId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_attachments\"}, {\"txt\": \"\", \"type\": \"dynamic\", \"varname\": \"additionalOptions\", \"sourceId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_additionalOptions\"}], \"output\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null}], \"prompt\": \"你是一名专业的会议纪要助手。  \\n请根据以下会议记录，整理成一份正式的会议纪要。  \\n\\n### 输出要求：\\n1. 使用 **Markdown 格式**，结构清晰、层级分明。  \\n2. 严格按照下列格式输出：  \\n\\n# 会议纪要  \\n\\n## 一、会议基本信息  \\n- **时间**：  \\n- **地点**：  \\n- **主持人**：  \\n- **记录人**：  \\n- **参会人员**：  \\n- **会议主题**：  \\n\\n---\\n\\n## 二、会议背景  \\n（说明会议召开原因或背景，如无则写“无”）  \\n\\n---\\n\\n## 三、会议内容概要  \\n### 1. 部门/议题/发言人A  \\n- 要点1  \\n- 要点2  \\n\\n### 2. 部门/议题/发言人B  \\n- 要点1  \\n- 要点2  \\n\\n---\\n\\n## 四、讨论要点  \\n- 讨论点1  \\n- 讨论点2  \\n- 分歧与共识  \\n\\n---\\n\\n## 五、决策与结论  \\n- 决策1  \\n- 决策2  \\n\\n---\\n\\n## 六、待办事项与行动计划  \\n- 任务1（负责人：XXX，截止日期：XXXX-XX-XX）  \\n- 任务2（负责人：XXX，截止日期：XXXX-XX-XX）  \\n\\n---\\n\\n## 七、风险与问题  \\n- 风险点1（待确认/需跟进）  \\n- 风险点2  \\n\\n---\\n\\n## 八、下次会议安排  \\n- **时间**：  \\n- **地点**：  \\n- **议题**：  \\n- **主持人**：  \\n\\n---\\n\\n### 语言要求：\\n- 简明扼要、专业客观，不写主观评价。  \\n- 冗长发言提炼为要点。  \\n- 不完整或模糊的信息用“（待确认）”标注。  \\n- 关键点可使用 **加粗**。  \\n\\n### 输入的会议记录：\\n---\\n{{8a7d9d77-a666-4e7d-9f95-66828db64506_additionalOptions}}\\n---\\n\\n### 请输出符合上述格式的会议纪要。\\n\", \"CanReadDoc\": false, \"CanReadPic\": false, \"sourceNodes\": {\"8a7d9d77-a666-4e7d-9f95-66828db64506\": {\"depth\": 1, \"label\": \"Start\", \"nodeId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506\", \"output\": [{\"id\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_prompt\", \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"prompt\", \"sourceId\": null, \"displayText\": \"prompt\", \"sourceNodeId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506\", \"sourceNodeLabel\": \"Start\"}, {\"id\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_currentTime\", \"txt\": \"当前时间\", \"type\": \"DateTime\", \"value\": \"{{currentTime}}\", \"nodeId\": null, \"varname\": \"currentTime\", \"sourceId\": null, \"displayText\": \"currentTime\", \"sourceNodeId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506\", \"sourceNodeLabel\": \"Start\"}, {\"id\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_attachments\", \"txt\": \"\", \"type\": \"List<AttachmentItem>\", \"value\": \"\", \"nodeId\": null, \"varname\": \"attachments\", \"sourceId\": null, \"displayText\": \"attachments\", \"sourceNodeId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506\", \"sourceNodeLabel\": \"Start\"}, {\"id\": \"8a7d9d77-a666-4e7d-9f95-66828db64506_additionalOptions\", \"txt\": \"\", \"type\": \"dynamic\", \"value\": \"\", \"nodeId\": null, \"varname\": \"additionalOptions\", \"sourceId\": null, \"displayText\": \"additionalOptions\", \"sourceNodeId\": \"8a7d9d77-a666-4e7d-9f95-66828db64506\", \"sourceNodeLabel\": \"Start\"}], \"isDirect\": true}}, \"temperature\": 50, \"NativeFunction\": [], \"SemanticFunction\": []}, \"name\": null, \"type\": \"LargeModel\", \"style\": {}, \"mainid\": \"2232fdeb-ac31-4d22-9f08-0b3194a408e2\", \"position\": {\"x\": 4.010470588235307, \"y\": -65.71376470588238}, \"fromNodeId\": \"\", \"workflowid\": \"c92046fa-3ccf-43ae-9182-25c7240fddba\", \"initialized\": false, \"fromNodeType\": 0}');
