INSERT INTO `tb_workflow_node_info` (`NodeID`, `WorkflowID`, `NodeType`, `NodeName`, `Description`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('c34f14cc-aaa1-4d59-bda1-2f8370b9fe3f', '6c8d595b-3494-4052-b486-aacec4806215', 'MainAI', 'Main AI', 'Main AI', '2026-05-11 11:03:56', '2026-05-11 11:03:56', '{\"id\": \"c34f14cc-aaa1-4d59-bda1-2f8370b9fe3f\", \"data\": {\"topp\": 60, \"label\": \"Main AI\", \"model\": {\"Name\": \"\", \"MICON\": \"\", \"MConfig\": \"\", \"EndPoint\": \"\", \"ModelKey\": \"\", \"TypeCode\": 0, \"TypeName\": \"\", \"ModelName\": \"\", \"CreateTime\": \"2025-08-21T10:28:25\", \"UpdateTime\": \"2025-08-21T10:28:25\", \"Description\": \"\", \"LargeModelID\": 5, \"SystemStatus\": 1, \"IsDefaultModel\": 0, \"ModelOrganizationID\": 0, \"ModelOrganizationName\": \"\"}, \"inputs\": [{\"txt\": \"\", \"type\": \"string\", \"varname\": \"\", \"sourceId\": \"\"}], \"output\": [{\"id\": null, \"txt\": \"\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null}], \"prompt\": \"你的名字叫：AgentBrook助手。\\n你是一个系统使用助手，是一个热情又专业的助手。\\n你的主要工作是向正在使用AgentBrook系统的用户提供帮助。\\n\\n#比如：\\n用户会向你提问（关于系统的具体功能的使用），你可以调用知识库的方式取得答案，并组织反馈给用户。如果没有找到相应的内容请不要随意回答，你可以直接回答（这个问题知识库中还没找到，我将记录下来。）\\n\\n#注意：\\n你的回答仅限于本系统的功能说明，操作步骤与解释。超过该范围的问题，都不能回答。\\n\\n每次都需要快速思考，可以从对话上下文中寻找已经回答的内容；回答内容需要简洁、专业。\\n\\n#用户的提问：\\n{{e6c2eb0a-de55-421e-bd7c-d16588ab5431_prompt}}\\n\\n#当前时间：\\n{{e6c2eb0a-de55-421e-bd7c-d16588ab5431_currentTime}}\\n\\n#Agent反馈的内容：\\n\", \"CanReadDoc\": false, \"CanReadPic\": false, \"sourceNodes\": {}, \"temperature\": 50, \"NativeFunction\": [], \"SemanticFunction\": []}, \"name\": null, \"type\": \"MainAI\", \"style\": {}, \"mainid\": \"15c5fb785f4ce8a99717ea85f29690c9\", \"position\": {\"x\": 20, \"y\": 85}, \"workflowid\": \"6c8d595b-3494-4052-b486-aacec4806215\", \"initialized\": false, \"fromNodeType\": 0}');
