INSERT INTO `tb_workflow_node_info` (`NodeID`, `WorkflowID`, `NodeType`, `NodeName`, `Description`, `CreateTime`, `LastUpdateTime`, `Config`) VALUES ('eff4e711-def8-4de1-8c40-3616fc01dc4f', '6c8d595b-3494-4052-b486-aacec4806215', 'End', 'End', 'End', '2026-05-11 11:03:56', '2026-05-11 11:03:56', '{\"id\": \"eff4e711-def8-4de1-8c40-3616fc01dc4f\", \"data\": {\"label\": \"End\", \"inputs\": [{\"txt\": \"\", \"type\": \"string\", \"varname\": \"results\", \"sourceId\": \"651dcba1-636d-43fa-8f81-cd4ecbc2d8ed_results\"}, {\"txt\": \"\", \"type\": \"string\", \"varname\": \"response\", \"sourceId\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4_response\"}, {\"txt\": \"\", \"type\": \"string\", \"varname\": \"results\", \"sourceId\": \"07fca914-6ac2-45be-bd5a-8ff719d86172_results\"}], \"prompt\": \"{{651dcba1-636d-43fa-8f81-cd4ecbc2d8ed_results}}\\n{{8df358d2-90b0-40e5-832c-0d0a72d7efe4_response}}\\n{{07fca914-6ac2-45be-bd5a-8ff719d86172_results}}\\n\", \"sourceNodes\": {\"07fca914-6ac2-45be-bd5a-8ff719d86172\": {\"depth\": 1, \"label\": \"Research\", \"nodeId\": \"07fca914-6ac2-45be-bd5a-8ff719d86172\", \"output\": [{\"id\": \"07fca914-6ac2-45be-bd5a-8ff719d86172_results\", \"txt\": \"研究结果(Markdown)\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"results\", \"sourceId\": null, \"displayText\": \"results\", \"sourceNodeId\": \"07fca914-6ac2-45be-bd5a-8ff719d86172\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"Research\", \"originalSourceId\": \"\"}, {\"id\": \"07fca914-6ac2-45be-bd5a-8ff719d86172_summary\", \"txt\": \"研究摘要\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"summary\", \"sourceId\": null, \"displayText\": \"summary\", \"sourceNodeId\": \"07fca914-6ac2-45be-bd5a-8ff719d86172\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"Research\", \"originalSourceId\": \"\"}, {\"id\": \"07fca914-6ac2-45be-bd5a-8ff719d86172_sources\", \"txt\": \"信息来源(JSON)\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"var