 \"nodeId\": null, \"varname\": \"completedSteps\", \"sourceId\": null, \"displayText\": \"completedSteps\", \"sourceNodeId\": \"651dcba1-636d-43fa-8f81-cd4ecbc2d8ed\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"Claw AI\", \"originalSourceId\": \"\"}, {\"id\": \"651dcba1-636d-43fa-8f81-cd4ecbc2d8ed_iterations\", \"txt\": \"迭代次数\", \"type\": \"int\", \"value\": \"\", \"nodeId\": null, \"varname\": \"iterations\", \"sourceId\": null, \"displayText\": \"iterations\", \"sourceNodeId\": \"651dcba1-636d-43fa-8f81-cd4ecbc2d8ed\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"Claw AI\", \"originalSourceId\": \"\"}, {\"id\": \"651dcba1-636d-43fa-8f81-cd4ecbc2d8ed_planningStatus\", \"txt\": \"规划状态\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"planningStatus\", \"sourceId\": null, \"displayText\": \"planningStatus\", \"sourceNodeId\": \"651dcba1-636d-43fa-8f81-cd4ecbc2d8ed\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"Claw AI\", \"originalSourceId\": \"\"}], \"isDirect\": true}, \"8df358d2-90b0-40e5-832c-0d0a72d7efe4\": {\"depth\": 1, \"label\": \"ServiceDesk\", \"nodeId\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4\", \"output\": [{\"id\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4_response\", \"txt\": \"回复内容\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"response\", \"sourceId\": null, \"displayText\": \"response\", \"sourceNodeId\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"ServiceDesk\", \"originalSourceId\": \"\"}, {\"id\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4_confidence\", \"txt\": \"置信度\", \"type\": \"string\", \"value\": \"\", \"nodeId\": null, \"varname\": \"confidence\", \"sourceId\": null, \"displayText\": \"confidence\", \"sourceNodeId\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4\", \"originalNodeId\": \"\", \"sourceNodeLabel\": \"ServiceDesk\", \"originalSourceId\": \"\"}, {\"id\": \"8df358d2-90b0-40e5-832c-0d0a72d7efe4_strategy\", \"txt\": \"处理策略\", \"t